"""Asclépios · bloc S8 (S8.7 à S8.12) : même format que s8_a.py."""
S8={}
S8['S8.7']=dict(src=['POLY','SCAND'],
c3="<b>SSP S8.7 — Traumatismes crâniens et cérébraux</b> · <i>head and brain injuries and trauma</i> · bloc S8 — Blessures et traumatismes.<br>On évalue et on note de manière répétée la conscience, les pupilles et le score de Glasgow, avec la réponse motrice des deux côtés (S3 Polytrauma, recommandation 2.10.1). On évite l’hypoxie et l’hypotension, qui aggravent la lésion du cerveau. Pour un traumatisme léger, les lignes scandinaves trient les patients : un scanner est indiqué en présence de facteurs de risque, et un patient à 15 sans facteur de risque peut rentrer sans scanner.",
c4="<b>Anamnèse</b><br>• Précise le mécanisme, une perte de connaissance, l’amnésie, les vomissements répétés et une crise d’épilepsie après le choc.<br>• Demande les anticoagulants, les antiagrégants et un trouble de la coagulation.<br>• Demande l’âge, l’alcool et les autres toxiques, qui gênent l’évaluation.<br><b>Drapeaux rouges</b><br>• Un score de Glasgow de 14 ou moins, une perte de connaissance, au moins deux vomissements, un anticoagulant, une crise après le choc, un déficit focal ou des signes de fracture du crâne imposent un scanner (lignes scandinaves 2013).<br>• Une dilatation d’une pupille, une réponse en extension ou une baisse de conscience qui s’aggrave signent un engagement cérébral (S3, 2.10.9).<br>• Une baisse de conscience qui survient après un intervalle libre fait craindre un hématome extradural.<br>• Un score de Glasgow de 8 ou moins impose l’intubation (S3, 2.10.3).<br>",
c6=None,
c12="• On répète le score de Glasgow et l’examen des pupilles, car c’est l’évolution qui compte (S3, 2.10.1).<br>• On vise une saturation au-dessus de 90 % et une pression systolique d’au moins 110 mmHg chez l’adulte (S3, 2.10.2 et 2.10.4).<br>• On ne donne pas de corticoïdes dans le traumatisme crânien (S3, 2.10.8).<br>• On refait un scanner si l’état neurologique s’aggrave (S3, 2.10.6).<br><b>Mémo</b> : Glasgow et pupilles répétés, oxygène, pression, scanner selon les facteurs de risque.",
c13="<b>Pièges</b><br>• Attribuer une baisse de conscience à l’alcool sans scanner.<br>• Renvoyer un patient âgé sous anticoagulant parce que l’examen est normal.<br>• Oublier que le traumatisme crânien va souvent avec une lésion du rachis cervical.<br>",
dd=[
("Hématome extradural",True,"Saignement entre l’os du crâne et la dure-mère, souvent d’origine artérielle après une fracture de l’os temporal.","Perte de connaissance brève, puis intervalle où le patient va bien, puis baisse rapide de la conscience, dilatation d’une pupille du côté de l’hématome.","Heures ; l’aggravation peut être très rapide.","Scanner en urgence et évacuation neurochirurgicale (S3, 2.10.5 et 2.10.6).","Renvoyer le patient pendant l’intervalle libre parce qu’il paraît aller bien.",['POLY']),
("Hématome sous-dural aigu",True,"Saignement entre la dure-mère et le cerveau par rupture de veines, fréquent chez la personne âgée ou sous anticoagulant.","Baisse de conscience souvent dès le choc, déficit focal, sujet âgé, chute, traitement anticoagulant.","Heures, parfois plusieurs jours chez la personne âgée.","Scanner, correction de la coagulation, avis neurochirurgical (lignes scandinaves 2013 ; S3, 2.10.5).","Juger un choc minime comme sans danger chez un patient sous anticoagulant.",['SCAND','POLY']),
("Engagement cérébral",True,"Déplacement du cerveau à travers les cloisons rigides du crâne quand la pression intracrânienne augmente.","Dilatation d’une pupille, réponse en extension à la douleur, baisse progressive de la conscience, puis troubles de la respiration et du pouls.","Minutes à heures.","Mesures d’urgence pour baisser la pression (hyperventilation, solution saline hypertonique ou mannitol) en attendant la chirurgie (S3, 2.10.9).","Attendre les troubles du pouls et de la respiration, qui sont très tardifs.",['POLY']),
("Fracture de la base du crâne",False,"Fracture du plancher du crâne, qui peut ouvrir l’espace des méninges vers le nez ou l’oreille.","Ecchymose autour des yeux ou derrière l’oreille, sang derrière le tympan, écoulement de liquide clair par le nez ou l’oreille (À vérifier).","Les signes apparaissent souvent après plusieurs heures.","Scanner, car ce sont des facteurs de risque (lignes scandinaves 2013) ; surveillance d’une méningite.","Prendre un écoulement nasal clair pour un simple rhume après un choc à la tête.",['SCAND']),
("Lésion du rachis cervical associée",True,"Fracture ou lésion ligamentaire du cou, fréquente avec un traumatisme crânien grave.","Patient inconscient ou confus qui ne peut pas signaler la douleur cervicale, mécanisme à haute énergie.","Immédiat.","Chez un patient inconscient, on considère qu’il y a une lésion du rachis jusqu’à preuve du contraire, et on fait un scanner du rachis (S3, 1.7.2 et 2.11.4).","Retirer la protection du cou sur la seule base d’un examen clinique chez un patient confus.",['POLY']),
])
S8['S8.8']=dict(src=['POLY','ESVS'],
c3="<b>SSP S8.8 — Traumatismes des extrémités</b> · <i>injuries of the extremities</i> · bloc S8 — Blessures et traumatismes.<br>Les traumatismes des extrémités comprennent les lésions des os, des articulations, des tendons, des vaisseaux et des nerfs des membres. Une hémorragie grave d’un membre se traite en priorité (S3 Polytrauma, recommandation 1.8.1). On examine tous les membres, on immobilise un membre suspect avant le transport, puis on confirme une fracture par radiographie en deux plans ou par scanner (1.8.3, 1.8.4 et 2.14.1).",
c4="<b>Anamnèse</b><br>• Précise le mécanisme, l’énergie, l’heure et la position du membre.<br>• Demande la douleur, les fourmillements, la faiblesse et le côté dominant pour la main.<br>• Demande le statut vaccinal contre le tétanos en cas de plaie.<br><b>Drapeaux rouges</b><br>• Une douleur disproportionnée qui augmente, surtout à l’étirement passif, fait craindre un syndrome de loge.<br>• Un membre pâle, froid ou sans pouls impose une recherche d’une lésion artérielle (S3, 2.14.6).<br>• Un os visible ou une plaie en regard d’une fracture signe une fracture ouverte, qui se nettoie grossièrement et se couvre d’un pansement stérile (S3, 1.8.6).<br>• Une déformation avec trouble de la circulation impose une réduction rapide (S3, 1.8.5).<br>• Un hématome qui grossit ou qui bat signe une lésion artérielle active.<br>",
c6="• <b>Syndrome de fracture</b> : douleur précise à la pression de l’os, déformation, mobilité anormale ou crépitation, impossibilité d’utiliser le membre ; on confirme par radiographie en deux plans (S3, 2.14.1).<br>• <b>Syndrome d’ischémie aiguë du membre</b> : membre pâle, froid, sans pouls, avec douleur, puis perte de sensibilité et de force ; c’est une urgence vasculaire (S3, 2.14.6 et 2.14.7).<br>• <b>Syndrome de loge</b> : douleur disproportionnée, douleur à l’étirement passif et loge tendue, alors que le pouls reste présent ; on peut mesurer la pression de la loge en cas de doute (S3, 2.14.9).<br>• <b>Syndrome d’atteinte nerveuse</b> : perte de sensibilité ou de force dans le territoire d’un nerf, à noter avant tout geste de réduction.<br>• <b>Syndrome de fracture ouverte</b> : plaie qui communique avec le foyer de fracture, avec un risque d’infection de l’os ; pansement stérile et chirurgie rapide (S3, 1.8.6 et 2.14.5).<br>",
c12="• On contrôle la circulation, la sensibilité et la force en aval avant et après chaque geste.<br>• On immobilise un membre suspect avant le transport (S3, 1.8.4).<br>• Une fracture ouverte reçoit un pansement stérile qui n’est plus ouvert avant le bloc opératoire (S3, 2.14.5).<br>• Un fragment amputé se conserve dans des compresses stériles humides, refroidi sans contact direct avec la glace (S3, 1.8.7).<br><b>Mémo</b> : hémorragie d’abord, puis circulation, nerfs, loge et peau.",
c13="<b>Pièges</b><br>• Croire qu’un pouls présent exclut un syndrome de loge : la pression de la loge dépasse celle des capillaires bien avant celle des artères.<br>• Se fier à une radiographie normale d’un scaphoïde douloureux : on immobilise et on contrôle, ou on fait une IRM (À vérifier).<br>• Oublier qu’une luxation du genou réduite spontanément peut cacher une lésion de l’artère poplitée.<br>• Ne pas chercher une fracture sur os fragile après un choc minime chez une personne âgée ou ayant un cancer.<br>",
dd=[
("Syndrome de loge",True,"Augmentation de la pression dans une loge musculaire fermée, qui comprime les vaisseaux et les nerfs, surtout après une fracture de la jambe ou de l’avant-bras.","Douleur disproportionnée qui augmente, douleur à l’étirement passif, loge tendue, fourmillements ; le pouls reste longtemps présent.","Heures ; les muscles souffrent en quelques heures.","Retirer ce qui serre, mesurer la pression de la loge si le doute persiste (S3, 2.14.9) et ouvrir la loge sans délai.","Attendre la perte du pouls pour agir.",['POLY']),
("Lésion artérielle d’un membre",True,"Section, déchirure ou thrombose d’une artère par une fracture, une luxation ou une plaie.","Membre pâle et froid, pouls absent ou diminué, hématome qui grossit, souffle ; fréquente après une luxation du genou ou une fracture du coude chez l’enfant.","Heures ; l’ischémie devient irréversible en quelques heures.","Angioscanner, écho-Doppler ou artériographie selon l’état du patient (S3, 2.14.6 et 2.14.7) ; l’index de pression systolique ne sert pas à poser ou exclure le diagnostic (ESVS 2025).","Attribuer un pied froid au choc ou au froid ambiant.",['POLY','ESVS']),
("Fracture ouverte",True,"Fracture avec une plaie qui fait communiquer le foyer avec l’extérieur.","Plaie en regard d’une fracture, os visible, saignement contenant des gouttes de graisse.","Heures ; le risque d’infection de l’os augmente avec le délai.","Nettoyage grossier, pansement stérile, immobilisation, antibiotique et chirurgie rapide (S3, 1.8.6 et 2.14.5) ; dose de l’antibiotique : À vérifier dans le Compendium.","Prendre une petite plaie pour une simple écorchure sans regarder la fracture en dessous.",['POLY']),
("Fracture du scaphoïde",False,"Fracture d’un petit os du poignet, à risque de mauvaise consolidation car sa vascularisation est fragile.","Chute sur la main en extension, douleur dans la tabatière anatomique et à la pression axiale du pouce.","La première radiographie peut être normale.","Immobilisation et nouvelle imagerie, ou IRM précoce si la douleur est évocatrice (À vérifier).","Conclure à une entorse du poignet sur une radiographie normale.",[]),
("Fracture sur os pathologique",False,"Fracture sur un os fragilisé par l’ostéoporose, une métastase ou une tumeur.","Choc minime, douleur qui existait avant la chute, personne âgée ou cancer connu, perte de poids.","Jours à semaines pour le bilan.","Radiographie et bilan de la cause (densité osseuse, recherche d’une tumeur) ; la chirurgie doit tenir compte de la cause.","Traiter la fracture sans chercher pourquoi l’os s’est cassé.",[]),
])
S8['S8.9']=dict(src=['POLY','ESVS'],
c3="<b>SSP S8.9 — Lacération, plaie ouverte ou fermée, hémorragie</b> · <i>laceration, closed or open wound, blood loss</i> · bloc S8 — Blessures et traumatismes.<br>Une hémorragie active se contrôle d’abord : compression manuelle, puis pansement compressif, puis garrot si la vie est menacée (S3 Polytrauma, recommandations 1.1.1, 1.1.5 et 1.1.9). Ensuite, on examine la plaie : profondeur, structures touchées en aval (tendons, nerfs, vaisseaux), souillure et corps étranger. On vérifie la protection contre le tétanos.",
c4="<b>Anamnèse</b><br>• Précise le mécanisme (coupure, morsure, écrasement, arme), l’heure et le lieu de l’accident (souillure).<br>• Demande les anticoagulants et le statut vaccinal contre le tétanos.<br>• Demande la main dominante et la profession pour une plaie de la main.<br><b>Drapeaux rouges</b><br>• Un saignement en jet ou qui reprend malgré la compression signe une plaie artérielle.<br>• Une perte de sensibilité ou de mouvement en aval fait suspecter une section de nerf ou de tendon.<br>• Une morsure ou une plaie très souillée a un risque élevé d’infection.<br>• Une plaie du cou, du thorax ou de l’abdomen peut cacher une lésion profonde grave.<br>",
c6="• <b>Syndrome hémorragique externe</b> : saignement visible ; on comprime, puis on pose un pansement compressif, et un garrot si la vie est menacée (S3, 1.1.5 et 1.1.9).<br>• <b>Syndrome de choc hémorragique</b> : pâleur, peau froide, tachycardie, puis baisse de la pression et de la conscience ; on cherche aussi un saignement interne.<br>• <b>Syndrome de lésion profonde</b> : perte de sensibilité, de mouvement ou de pouls en aval d’une plaie ; on teste chaque tendon et chaque nerf avant l’anesthésie locale.<br>• <b>Syndrome d’infection de plaie</b> : rougeur, chaleur, douleur qui augmente, écoulement de pus ou fièvre après quelques jours.<br>• <b>Syndrome de plaie fermée</b> : hématome ou décollement sous une peau intacte après un écrasement, avec risque de nécrose de la peau.<br>",
c12="• La compression manuelle directe est le premier geste ; le garrot sert quand elle ne suffit pas (S3, 1.1.5 et 1.1.9).<br>• On teste la sensibilité et les tendons avant l’anesthésie locale.<br>• On explore la plaie à la recherche d’un corps étranger et d’une lésion profonde.<br>• On vérifie la vaccination contre le tétanos (schéma : À vérifier dans le plan suisse de vaccination).<br><b>Mémo</b> : comprimer, explorer, tester en aval, nettoyer, protéger contre le tétanos.",
c13="<b>Pièges</b><br>• Contrôler toutes les minutes si le saignement s’est arrêté pendant la compression manuelle (S3, 1.1.6).<br>• Fermer une plaie de la main sans avoir testé chaque tendon.<br>• Fermer une morsure très souillée comme une coupure propre.<br>• Oublier le tétanos.<br>",
dd=[
("Plaie artérielle",True,"Section ou déchirure d’une artère, avec saignement externe ou hématome.","Saignement rouge vif en jet ou pulsatile, hématome qui grossit ou bat, pouls absent en aval.","Minutes.","Compression manuelle, pansement compressif, garrot si la vie est menacée (S3, 1.1.5 et 1.1.9), puis scanner avec produit de contraste ou chirurgie (S3, 2.6.2).","Relâcher la compression pour regarder la plaie.",['POLY']),
("Section de tendon ou de nerf",False,"Coupure d’un tendon fléchisseur ou extenseur, ou d’un nerf, surtout à la main et au poignet.","Doigt qui ne fléchit ou ne s’étend plus, position anormale du doigt au repos, perte de sensibilité d’un côté du doigt.","Heures à jours ; la réparation est meilleure si elle est précoce.","Test de chaque tendon et de la sensibilité avant l’anesthésie locale, exploration et réparation par un chirurgien de la main.","Tester après l’anesthésie locale ou ne pas tester du tout.",[]),
("Corps étranger dans la plaie",False,"Fragment de verre, de bois ou de métal resté dans la plaie.","Douleur à un point précis, sensation de corps étranger, plaie qui ne guérit pas ou s’infecte.","Jours.","Exploration de la plaie, radiographie pour le verre et le métal, échographie pour le bois (À vérifier).","Fermer une plaie par un éclat de verre sans l’avoir explorée.",[]),
("Infection de plaie et de morsure",False,"Infection bactérienne d’une plaie, plus fréquente après une morsure, un écrasement ou une souillure.","Rougeur, chaleur, douleur qui augmente, pus, traînée rouge vers la racine du membre, fièvre.","Un à trois jours.","Nettoyage, avis sur la fermeture, antibiotique selon le cas (dose : À vérifier dans le Compendium).","Fermer une morsure de la main comme une plaie propre.",[]),
("Tétanos",True,"Maladie due à une toxine bactérienne qui provoque des contractures musculaires, après une plaie chez une personne mal vaccinée.","Contracture des mâchoires, puis de la nuque et du tronc, spasmes provoqués par le bruit ou le toucher.","Jours à semaines après la plaie.","Prévention par la vaccination et les immunoglobulines selon le statut vaccinal (schéma : À vérifier dans le plan suisse de vaccination).","Oublier de vérifier le carnet de vaccination d’un adulte âgé.",[]),
])
S8['S8.10']=dict(src=['POLY'],
c3="<b>SSP S8.10 — Traumatismes rachidiens</b> · <i>spine injuries</i> · bloc S8 — Blessures et traumatismes.<br>On examine le rachis et les fonctions qui en dépendent (S3 Polytrauma, recommandation 1.7.1). Chez un patient inconscient, on considère qu’il y a une lésion du rachis jusqu’à preuve du contraire (1.7.2). Une fois le patient stable, le scanner du crâne au bassin est l’examen préféré ; à défaut, on fait des radiographies de tout le rachis (2.11.3 et 2.11.4).",
c4="<b>Anamnèse</b><br>• Précise le mécanisme : chute de hauteur, accident à haute énergie, plongeon.<br>• Demande la douleur du cou ou du dos, les fourmillements, la faiblesse et les troubles urinaires.<br>• Demande une maladie qui rend le rachis fragile : spondylarthrite ankylosante ou ostéoporose.<br><b>Drapeaux rouges</b><br>• Un déficit moteur ou sensitif, même partiel, impose le transport vers un centre de traumatologie adapté (S3, 1.7.5).<br>• Une hypotension avec un pouls lent fait penser à un choc neurogène.<br>• Une respiration abdominale ou difficile après un traumatisme cervical signe une atteinte haute de la moelle.<br>• Une rétention urinaire ou une perte de sensibilité du périnée signe une atteinte de la queue de cheval.<br>",
c6="• <b>Syndrome de section médullaire complète</b> : perte de toute force et de toute sensibilité sous le niveau de la lésion, y compris au périnée ; on recherche un choc neurogène.<br>• <b>Syndrome centromédullaire</b> : faiblesse plus marquée aux bras qu’aux jambes, souvent après une hyperextension du cou chez une personne âgée.<br>• <b>Syndrome de Brown-Séquard</b> : faiblesse d’un côté et perte de la sensibilité à la douleur et à la température de l’autre côté, après une plaie ou une lésion d’une moitié de la moelle.<br>• <b>Syndrome de la queue de cheval</b> : douleur, faiblesse des jambes, perte de sensibilité du périnée et rétention urinaire après une lésion lombaire.<br>• <b>Syndrome rachidien sans déficit</b> : douleur à la pression d’une épineuse et douleur au mouvement ; on fait l’imagerie selon le mécanisme (S3, 2.11.4).<br>",
c12="• On examine et on note la force, la sensibilité et le niveau de la lésion, y compris au périnée, de façon répétée.<br>• Chez un patient inconscient, on suppose une lésion du rachis (S3, 1.7.2).<br>• On protège le rachis cervical pendant la désincarcération, sauf s’il faut sortir le patient immédiatement d’un danger (S3, 1.7.3).<br>• Un examen de radiographie suspect ou mal lisible se complète par un scanner (S3, 2.11.5).<br><b>Mémo</b> : supposer la lésion, examiner le niveau, imager après stabilisation, centre adapté si déficit.",
c13="<b>Pièges</b><br>• Attribuer une hypotension au saignement seul chez un patient paralysé des quatre membres au pouls lent.<br>• Manquer une fracture sur un rachis rigide de spondylarthrite ankylosante après un choc minime.<br>• Oublier l’examen du périnée et de la sensibilité autour de l’anus.<br>",
dd=[
("Lésion de la moelle cervicale",True,"Atteinte de la moelle épinière au niveau du cou par fracture, luxation ou hyperextension.","Déficit des quatre membres, respiration abdominale, priapisme, perte de sensibilité avec un niveau précis.","Immédiat ; l’œdème peut faire monter le niveau dans les heures suivantes.","Protection du rachis, oxygène, maintien de la pression, scanner après stabilisation et transfert vers un centre adapté (S3, 1.7.5 et 2.11.4).","Ne pas surveiller la respiration, qui peut se dégrader quand le niveau monte.",['POLY']),
("Choc neurogène",True,"Perte du tonus des vaisseaux et ralentissement du cœur après une lésion de la moelle cervicale ou thoracique haute.","Hypotension avec pouls lent ou normal, peau chaude et rose sous le niveau de la lésion.","Minutes à heures.","Remplissage prudent et médicaments qui resserrent les vaisseaux ; on cherche toujours un saignement associé (À vérifier).","Croire qu’un choc chez un blessé est toujours hémorragique, ou au contraire tout attribuer à la moelle.",[]),
("Fracture instable du rachis sans déficit",True,"Fracture ou lésion des ligaments qui peut déplacer les vertèbres et léser la moelle lors d’un mouvement.","Douleur à la pression d’une épineuse, mécanisme à haute énergie, marche en escalier à la palpation, pas de déficit.","Le danger survient lors d’une mobilisation.","Protection du rachis, scanner du crâne au bassin (S3, 2.11.4), avis de chirurgie du rachis ; pas de réduction sans scanner (S3, 2.11.6).","Mobiliser le patient avant d’avoir l’imagerie.",['POLY']),
("Syndrome de la queue de cheval",True,"Compression des racines nerveuses lombaires et sacrées sous la fin de la moelle.","Douleur des jambes, faiblesse, perte de sensibilité du périnée, rétention urinaire ou perte du contrôle de l’anus.","Heures ; la récupération de la vessie dépend du délai.","Examen du périnée, imagerie en urgence et décompression chirurgicale (À vérifier).","Ne pas examiner le périnée et ne pas mesurer le résidu urinaire.",[]),
("Fracture sur rachis rigide",True,"Fracture d’un rachis soudé par une spondylarthrite ankylosante ou une autre maladie qui soude les vertèbres, qui se comporte comme un os long.","Douleur nouvelle après un choc minime, rachis déjà rigide, posture voûtée connue.","Le déficit peut apparaître secondairement.","Imagerie par scanner de tout le rachis, maintien de la position habituelle du patient (À vérifier).","Forcer le cou d’un patient voûté pour le mettre à plat.",[]),
])
S8['S8.11']=dict(src=['POLY'],
c3="<b>SSP S8.11 — Traumatismes thoraciques</b> · <i>thoracic injuries</i> · bloc S8 — Blessures et traumatismes.<br>On recueille le mécanisme : un accident à haute vitesse ou un choc latéral fait craindre une rupture de l’aorte (S3 Polytrauma, recommandation 2.7.2). On compte la fréquence respiratoire, on écoute les deux poumons et on répète l’examen (1.5.2). Chez le patient instable, l’échographie élargie (eFAST) cherche un pneumothorax, un hémothorax et une tamponnade ; chez le patient stable avec signes de gravité, on fait un scanner du thorax avec produit de contraste (2.7.5, 2.7.6 et 2.7.17).",
c4="<b>Anamnèse</b><br>• Précise le mécanisme : vitesse, décélération, choc latéral, ceinture, volant, arme blanche ou arme à feu.<br>• Demande la douleur, la gêne respiratoire et la toux avec du sang.<br>• Demande les anticoagulants et une maladie pulmonaire connue.<br><b>Drapeaux rouges</b><br>• Un murmure absent d’un côté avec une détresse respiratoire ou circulatoire fait suspecter un pneumothorax compressif, à décomprimer immédiatement (S3, 1.5.7 et 1.5.8).<br>• Une hypotension avec des veines du cou gonflées après une plaie du thorax fait craindre une tamponnade (S3, 2.7.16 et 2.7.17).<br>• Un volet thoracique, c’est-à-dire une partie de la paroi qui rentre à l’inspiration, signe des fractures de côtes multiples et une contusion du poumon.<br>• Un saignement important par le drain thoracique fait discuter une thoracotomie (S3, 2.7.18).<br>",
c6="• <b>Syndrome d’épanchement gazeux</b> : murmure diminué ou absent d’un côté, son tympanique à la percussion ; sous tension, s’y ajoutent détresse respiratoire, hypotension et veines du cou gonflées (S3, 1.5.5 et 1.5.7).<br>• <b>Syndrome d’épanchement liquidien</b> : murmure diminué et matité à la percussion d’un côté, avec signes de choc s’il s’agit d’un hémothorax important (S3, 2.7.13).<br>• <b>Syndrome de tamponnade</b> : hypotension, veines du cou gonflées, bruits du cœur assourdis ; l’eFAST confirme l’épanchement autour du cœur (S3, 2.7.17).<br>• <b>Syndrome pariétal</b> : douleur à la pression des côtes, crépitation, emphysème sous-cutané, mouvement paradoxal d’un volet.<br>• <b>Syndrome de contusion du cœur</b> : troubles du rythme ou douleur thoracique après un choc frontal ; on fait un électrocardiogramme à 12 dérivations et une troponine (S3, 2.7.8).<br>",
c12="• On répète l’examen, car un petit pneumothorax peut s’aggraver, surtout sous ventilation (S3, 1.5.6).<br>• Un pneumothorax compressif suspecté se décomprime sans attendre l’imagerie (S3, 1.5.8).<br>• Un pneumothorax ouvert se couvre d’un pansement à valve (S3, 1.5.14).<br>• On surveille le rythme cardiaque en continu (S3, 2.7.7).<br><b>Mémo</b> : compter, écouter, percuter, répéter ; décomprimer sur la clinique, pas sur l’image.",
c13="<b>Pièges</b><br>• Attendre une radiographie pour traiter un pneumothorax compressif.<br>• Oublier de vérifier la position du tube avant de conclure à un murmure absent d’un côté (S3, 1.5.5).<br>• Se rassurer par une radiographie normale chez un patient qui a eu une décélération violente : la rupture de l’aorte se cherche au scanner.<br>• Faire une thoracotomie d’urgence chez un patient sans signe de vie sur les lieux après un traumatisme fermé (S3, 2.7.20).<br>",
dd=[
("Pneumothorax compressif",True,"Air sous pression dans la plèvre qui écrase le poumon et gêne le retour du sang au cœur.","Murmure absent d’un côté, détresse respiratoire, hypotension, veines du cou gonflées ; surtout chez un patient ventilé.","Minutes.","Décompression immédiate à l’aiguille ou par une petite ouverture du thorax, puis drain thoracique (S3, 1.5.8, 1.5.11 et 2.7.9).","Attendre la radiographie, ou se fier au déplacement de la trachée, qui est tardif.",['POLY']),
("Hémothorax massif",True,"Saignement important dans la plèvre à partir des vaisseaux de la paroi, du poumon ou des gros vaisseaux.","Murmure diminué et matité d’un côté, choc, saignement abondant par le drain.","Minutes à heures.","Drain thoracique de gros calibre chez le patient instable, thoracotomie si le saignement est important ou continue (S3, 2.7.13, 2.7.14 et 2.7.18).","Clamper le drain pour ralentir le saignement au lieu d’appeler le chirurgien.",['POLY']),
("Tamponnade",True,"Sang dans le péricarde qui empêche le cœur de se remplir, surtout après une plaie pénétrante.","Hypotension, veines du cou gonflées, bruits du cœur assourdis, épanchement autour du cœur à l’eFAST.","Minutes.","eFAST chez tout patient instable avec traumatisme thoracique, drainage du péricarde si l’état se dégrade (S3, 2.7.16 et 2.7.17).","Prendre les veines du cou gonflées pour un pneumothorax seul, ou ne pas les voir chez un patient qui a beaucoup saigné.",['POLY']),
("Rupture traumatique de l’aorte",True,"Déchirure de l’aorte thoracique par décélération brutale, souvent contenue au début par sa paroi externe.","Accident à haute vitesse ou choc latéral, douleur dans le dos, différence de pression entre les bras, médiastin élargi.","Heures ; la rupture complète est souvent mortelle.","Scanner du thorax avec produit de contraste (S3, 2.7.2 et 2.7.6), traitement endovasculaire, si possible après les 24 premières heures quand la lésion le permet (S3, 2.6.4).","Se rassurer par une radiographie du thorax normale.",['POLY']),
("Contusion du cœur",False,"Lésion du muscle cardiaque par un choc direct sur le sternum.","Choc frontal, douleur thoracique, troubles du rythme, sang dans la troponine.","Heures ; les troubles du rythme surviennent surtout au début.","Électrocardiogramme à 12 dérivations et troponine, surveillance du rythme (S3, 2.7.7 et 2.7.8).","Renvoyer un patient avec un électrocardiogramme anormal après un choc sur le sternum.",['POLY']),
])
